import React, { useState } from 'react';
import { Form, InputNumber, Button, Card, message, Space, Divider } from 'antd';
import { SaveOutlined } from '@ant-design/icons';

/**
 * ThresholdForm - Form component for creating/editing threshold profiles
 * Generated by Copilot
 */
const ThresholdForm = ({ onSubmit, initialValues = null, loading = false }) => {
  const [form] = Form.useForm();

  const defaultValues = {
    systolic_healthy_min: 90,
    systolic_healthy_max: 120,
    systolic_borderline_min: 120,
    systolic_borderline_max: 140,
    diastolic_healthy_min: 60,
    diastolic_healthy_max: 80,
    diastolic_borderline_min: 80,
    diastolic_borderline_max: 90,
    heart_rate_min: 60,
    heart_rate_max: 100
  };

  const handleSubmit = async (values) => {
    // Transform form values to API format
    const payload = {
      systolic_healthy: [values.systolic_healthy_min, values.systolic_healthy_max],
      systolic_borderline: [values.systolic_borderline_min, values.systolic_borderline_max],
      diastolic_healthy: [values.diastolic_healthy_min, values.diastolic_healthy_max],
      diastolic_borderline: [values.diastolic_borderline_min, values.diastolic_borderline_max],
      systolic_min: values.systolic_healthy_min,
      systolic_max: values.systolic_borderline_max,
      diastolic_min: values.diastolic_healthy_min,
      diastolic_max: values.diastolic_borderline_max
    };

    if (values.heart_rate_min && values.heart_rate_max) {
      payload.heart_rate_min = values.heart_rate_min;
      payload.heart_rate_max = values.heart_rate_max;
    }

    try {
      await onSubmit(payload);
      message.success('阈值配置已保存为草稿');
    } catch (error) {
      message.error(error.message || '保存失败');
    }
  };

  return (
    <Card title="阈值配置" bordered={false}>
      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
        initialValues={initialValues || defaultValues}
      >
        <Divider orientation="left">收缩压 (Systolic)</Divider>
        <Space size="large">
          <Form.Item
            label="健康范围下限"
            name="systolic_healthy_min"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>

          <Form.Item
            label="健康范围上限"
            name="systolic_healthy_max"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>
        </Space>

        <Space size="large">
          <Form.Item
            label="边界范围下限"
            name="systolic_borderline_min"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>

          <Form.Item
            label="边界范围上限"
            name="systolic_borderline_max"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>
        </Space>

        <Divider orientation="left">舒张压 (Diastolic)</Divider>
        <Space size="large">
          <Form.Item
            label="健康范围下限"
            name="diastolic_healthy_min"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>

          <Form.Item
            label="健康范围上限"
            name="diastolic_healthy_max"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>
        </Space>

        <Space size="large">
          <Form.Item
            label="边界范围下限"
            name="diastolic_borderline_min"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>

          <Form.Item
            label="边界范围上限"
            name="diastolic_borderline_max"
            rules={[
              { required: true, message: '请输入数值' },
              { type: 'number', min: 30, max: 250, message: '范围: 30-250' }
            ]}
          >
            <InputNumber min={30} max={250} addonAfter="mmHg" />
          </Form.Item>
        </Space>

        <Divider orientation="left">心率 (Heart Rate - 可选)</Divider>
        <Space size="large">
          <Form.Item
            label="最低心率"
            name="heart_rate_min"
            rules={[
              { type: 'number', min: 30, max: 150, message: '范围: 30-150' }
            ]}
          >
            <InputNumber min={30} max={150} addonAfter="bpm" />
          </Form.Item>

          <Form.Item
            label="最高心率"
            name="heart_rate_max"
            rules={[
              { type: 'number', min: 30, max: 150, message: '范围: 30-150' }
            ]}
          >
            <InputNumber min={30} max={150} addonAfter="bpm" />
          </Form.Item>
        </Space>

        <Form.Item>
          <Button 
            type="primary" 
            htmlType="submit" 
            icon={<SaveOutlined />}
            loading={loading}
          >
            保存草稿
          </Button>
        </Form.Item>
      </Form>
    </Card>
  );
};

export default ThresholdForm;
